INSERT INTO projects(project_id,site_id,project,status,date,capacity_note,water_change,source_id) VALUES
('P070-01','CN0063','19000吨/年脱硝催化剂处置再生及资源化项目污水处理系统设备治理工程（二次）','2026-11-27中标候选人公示索引；未取得正式结果','2026-11-27','19000t/a废催化剂项目规模，不是水量','建筑及安装工程，技术规范书、报价及供应商未取得；不得认定仍可投标','S070-02'),
('P070-02','CN0093','500t/a硝酸法、100t/a浸渍法化肥催化剂柔性生产装置技改','正式环评批复目录；施工一标段中标结果转载','2026-11','宁新区管政环建〔2026〕13号；原项目规模不重复计','批复DOCX附件正文未取得，污水分股及工程合同边界待核','S070-03');
INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N070-01','CN0291','S040-04','报告再提取：母公司与总排口边界','表3.3.3.2-7 pp154–155及p151','企业统计2023母公司67175t/a，达产131081.65t/a；另总排口含子公司8.7万t/a。10万t/a异丙胺和1.5万t/a乙胺装置脱水废水回用到产品配置、外排列0，实际生成量未知；双氧水2023列0，达产1377。冷却排污2023大部分已改造，少部分直流外排，不能套用2026。原表雨水COD约60mg/L后有附加字符10，按60约值保留；截图超限，正文可读。与W060-22是细化同一历史总量，不能加总。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N070-02','CN0249','S020-001','报告再提取：膜前后及残余物','表4.8-6/7、4.8.3 pp54–56及地表水评价','原表酸洗进出水列pH1–2至7–8，其余进水浓度与中和后断面吻合；不把中和前后量及浓度强配。RO浓水返回ED，ED浓水三效，冷凝回用于酸洗。三效盐泥128.12t/a与压滤废渣1.47t/a为设计危废；报告所称活性炭酸洗口径与特种催化剂混合项目关系待核。图4.8-2盐水平衡因商业信息删除，不能推算膜回收率。截图超时，采用原文可读数字与上下文表序；pH口径异文保留。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N070-03','CN0254','S023-003','报告再提取：公辅与多级处理浓度','表4.8.2-1至4 pp89–91','原有3.583m³/a绿色有机催化剂压滤水及总量5033.703已入库；本轮补5公辅流股、450m³/d电芬顿设计浓度与800m³/d综合站额定设计、混合中试物化和厌氧分段。设计进水COD10000与混合中试1839.6不同，不能相加；原报告全盐量701.28与末端701.31有小差异，不擅自改；两项未命名行不猜污染物。截图超时，原报告表文本可读。既有运行阶段event_hold保持。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N070-04','CN0254','S023-004','后续技改报告复核建设阶段','表2.4-6、2.5-1','该10万吨聚氨酯技改报告将5033.703m³/a催化剂混合中试列为在建设计，非实测；现有全厂297539.5m³/a为报告现有口径，另在建42371.332m³/a。非催化剂单线，不将其重复作为新中试水量。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N070-05','CN0063','S070-01','新招标事件','11月3日二次招标转载；11月27日中标候选索引S070-02','二次招标及候选人公示标题与项目一致，未核原候选名单、合同、具体装置参数或金额；单独于历史MBR/RO运行披露。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N070-06','CN0093','S070-03','已知项目新证据','7月17日审批决定附件目录及11月施工结果转载S070-04','正式批复号宁新区管政环建〔2026〕13号；施工总承包一标段结果公示不等于污水设备中标。未获取批复全文或价格。','WEB_PRIMARY','WEB_TEXT','2026-11-28');
