-- 070 document reuse and current project events; no commercial restructuring
PRAGMA foreign_keys=ON;
BEGIN;

-- Structured attempt history. Dates are calendar days, China time, not invented hours.
CREATE TABLE research_revisit_attempts(
 attempt_id TEXT PRIMARY KEY,
 site_id TEXT NOT NULL REFERENCES sites(site_id),
 scope_key TEXT NOT NULL,
 gap TEXT NOT NULL,
 route_key TEXT NOT NULL,
 search_log_id TEXT NOT NULL UNIQUE REFERENCES search_log(log_id),
 source_id TEXT REFERENCES sources(source_id),
 checked_on TEXT NOT NULL CHECK(date(checked_on) IS NOT NULL),
 outcome TEXT NOT NULL CHECK(outcome IN ('engineering_gain','context_gain','duplicate','no_new','access_blocked','event_pending','private_required','unassessed')),
 gained_fields TEXT NOT NULL,
 evidence_refs TEXT NOT NULL,
 effort_minutes REAL CHECK(effort_minutes IS NULL OR effort_minutes>=0),
 next_check_on TEXT CHECK(next_check_on IS NULL OR (date(next_check_on) IS NOT NULL AND next_check_on>=checked_on)),
 reopen_trigger TEXT NOT NULL,
 rationale TEXT NOT NULL,
 FOREIGN KEY(site_id,source_id) REFERENCES site_sources(site_id,source_id)
);
CREATE TABLE research_reopen_events(
 event_id TEXT PRIMARY KEY,
 site_id TEXT NOT NULL REFERENCES sites(site_id),
 scope_key TEXT NOT NULL,
 gap TEXT NOT NULL,
 route_key TEXT NOT NULL,
 event_kind TEXT NOT NULL,
 source_id TEXT NOT NULL,
 observed_on TEXT NOT NULL CHECK(date(observed_on) IS NOT NULL),
 event_detail TEXT NOT NULL,
 consumed_by_attempt TEXT REFERENCES research_revisit_attempts(attempt_id),
 FOREIGN KEY(site_id,source_id) REFERENCES site_sources(site_id,source_id)
);
CREATE TABLE research_document_review(
 site_id TEXT NOT NULL,
 source_id TEXT NOT NULL,
 scope_key TEXT NOT NULL,
 gap TEXT NOT NULL,
 reviewed_on TEXT NOT NULL CHECK(date(reviewed_on) IS NOT NULL),
 state TEXT NOT NULL CHECK(state IN ('partial','section_done','blocked','needs_review','wrong_scope')),
 locator TEXT NOT NULL,
 remaining_work TEXT NOT NULL,
 next_check_on TEXT CHECK(next_check_on IS NULL OR (date(next_check_on) IS NOT NULL AND next_check_on>=reviewed_on)),
 attempt_id TEXT REFERENCES research_revisit_attempts(attempt_id),
 PRIMARY KEY(site_id,source_id,scope_key,gap),
 FOREIGN KEY(site_id,source_id) REFERENCES site_sources(site_id,source_id)
);
CREATE VIEW v_research_revisit_latest AS
 SELECT * FROM (SELECT a.*,row_number() OVER(PARTITION BY site_id,scope_key,gap,route_key ORDER BY checked_on DESC,attempt_id DESC) AS rn FROM research_revisit_attempts a) WHERE rn=1;
CREATE VIEW v_research_revisit_due AS
 SELECT a.*,CASE
 WHEN EXISTS(SELECT 1 FROM research_reopen_events e WHERE e.site_id=a.site_id AND e.scope_key=a.scope_key AND e.gap=a.gap AND e.route_key=a.route_key AND e.consumed_by_attempt IS NULL) THEN 'event_ready'
 WHEN next_check_on IS NULL THEN 'event_only'
 WHEN next_check_on<=date('now','+8 hours') THEN 'due'
 ELSE 'cooldown' END AS revisit_status
 FROM v_research_revisit_latest a;
CREATE VIEW v_document_backlog_candidates AS
 SELECT q.site_id,q.name,q.next_gap,q.public_disposition,s.source_id,s.title,s.url,s.source_type,s.document_date,
 (SELECT count(*) FROM water_metrics m WHERE m.site_id=q.site_id AND m.source_id=s.source_id) AS metrics_from_source,
 (SELECT count(*) FROM wastewater w WHERE w.site_id=q.site_id AND w.source_id=s.source_id) AS water_from_source
 FROM v_public_research_queue q JOIN site_sources l USING(site_id) JOIN sources s USING(source_id)
 WHERE q.public_disposition IN ('core_public','bounded_public')
 AND (lower(s.url) LIKE '%.pdf%' OR s.source_type LIKE '%验收监测报告%' OR s.source_type LIKE '%政府公开环评%')
 AND (s.title LIKE '%环评%' OR s.title LIKE '%环境影响%' OR s.title LIKE '%验收%')
 AND s.source_type NOT LIKE '%索引%' AND s.title NOT LIKE '%索引%' AND s.title NOT LIKE '%拟审批%' AND s.title NOT LIKE '%首次公示%' AND s.title NOT LIKE '%拟批%';
CREATE VIEW v_research_document_dispatch AS
 SELECT d.*,r.state,r.locator,r.remaining_work,r.reviewed_on,r.next_check_on,
 CASE WHEN r.state='wrong_scope' THEN 'exclude_this_scope'
 WHEN r.state='section_done' THEN 'section_done'
 WHEN r.state='blocked' AND (r.next_check_on IS NULL OR r.next_check_on>date('now','+8 hours')) THEN 'recovery_cooldown'
 WHEN r.state='blocked' THEN 'recover_new_path'
 WHEN r.state='partial' THEN 'extract_remaining_section'
 ELSE 'verify_scope_and_access' END AS document_action
 FROM v_document_backlog_candidates d
 LEFT JOIN research_document_review r ON r.site_id=d.site_id AND r.source_id=d.source_id AND r.scope_key='site_current' AND r.gap=d.next_gap;
CREATE VIEW v_research_dispatch AS
 SELECT q.*,a.checked_on AS last_structured_review,a.outcome AS last_outcome,a.next_check_on,a.reopen_trigger AS revisit_trigger,
 CASE WHEN q.public_disposition NOT IN ('core_public','bounded_public') THEN 'preserve_'||q.public_disposition
 WHEN a.revisit_status='event_ready' THEN 'review_new_event'
 WHEN a.revisit_status='cooldown' THEN 'pause_generic_search'
 WHEN a.revisit_status='event_only' THEN 'await_event'
 WHEN a.revisit_status='due' THEN 'bounded_new_path'
 ELSE 'unassessed_use_original_queue' END AS dispatch_action
 FROM v_public_research_queue q LEFT JOIN v_research_revisit_due a ON a.site_id=q.site_id AND a.scope_key='site_current' AND a.gap=q.next_gap AND a.route_key='general_public';
CREATE VIEW v_research_existing_hold_clock AS
 SELECT site_id,'site' AS scope_key,'整主体暂缓' AS gap,disposition,reviewed_on,
 CASE disposition WHEN 'stalled_hold' THEN date(reviewed_on,'+90 days') WHEN 'weak_identity_hold' THEN date(reviewed_on,'+120 days') ELSE NULL END AS review_after,
 reopen_trigger FROM task_triage
 UNION ALL
 SELECT site_id,'gap',gap,disposition,reviewed_on,
 CASE disposition WHEN 'event_hold' THEN date(reviewed_on,'+30 days') ELSE NULL END,reopen_trigger FROM research_gap_hold;

COMMIT;
